use corpse_core::{startup,generation as g};use serde_json::json;
fn inspect(tag:&str,f:&corpse_core::Floor){let seen=g::reachable_without_braziers(f,None);let trans=g::automatic_transitions(f);println!("{tag} valid={} accessible={} transitions={trans:?}",g::validate_floor_generation(f),g::transitions_accessible(f,&seen));for at in &trans{let near=g::cardinal_neighbors(*at,f.width(),f.height());if !near.iter().any(|n|seen.contains(n)&&!trans.contains(n)){println!("{}",json!({"tag":tag,"depth":f.depth,"at":at,"xy":[at%f.width(),at/f.width()],"tile":f.tiles[*at],"near":near.iter().map(|n|json!({"at":n,"tile":f.tiles[*n],"seen":seen.contains(n),"fire":g::fire_cells(f).contains(n)})).collect::<Vec<_>>(),"godbeast":f.godbeast_event,"sphinx":f.sphinx_room,"biomes":f.pocket_biomes}));}}}
fn main(){let mut r=startup::new_run_shell_revision("r37-event-count-0078","Unblessed",false,38.).unwrap();startup::ensure_floors(&mut r,40).unwrap();let f=&r.floors[29];inspect("populated",f);let prev=&r.floors[28];let at=prev.tiles.iter().position(|t|t=="down").unwrap();let up=Some(g::Point{x:(at%prev.width())as i32,y:(at/prev.width())as i32});let pure=g::generate_floor_full_revision(30,corpse_core::rng::seed_hash(&r.seed),up,38.).unwrap();inspect("geometry",&pure);std::fs::write(std::env::args().nth(1).unwrap(),serde_json::to_string(f).unwrap()).unwrap();}
